.sliceCanvas {
  width: 100%;
  height: auto;
  border: 1px solid var(--border-color);
  border-radius: 2px;
  background-color: var(--bg-main);
}

/* NiiViewer 樣式 */
.niiViewerContainer {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.niiViewerHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.viewerTitle {
  margin: 0;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
}

.downloadButtonLink {
  padding: 8px 16px;
  font-size: 0.875rem;
  font-weight: 400;
  border: 1px solid var(--coral-primary);
  border-radius: 6px;
  background-color: transparent;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  text-decoration: none;
}

.downloadButtonLink:hover:not(.disabled) {
  background-color: transparent;
  border-color: var(--coral-primary);
  color: var(--coral-primary);
  box-shadow: 0 0 0 2px rgba(255, 127, 80, 0.2);
}

.downloadButtonLink:active:not(.disabled) {
  background-color: transparent;
  border-color: var(--coral-dark);
  color: var(--coral-dark);
  transform: scale(0.95);
}

.downloadButtonLink:focus:not(.disabled) {
  outline: none;
  box-shadow: 0 0 0 3px rgba(255, 127, 80, 0.3);
}

.downloadButtonLink.disabled {
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}

return (
  <div className={styles.niiViewerContainer}>
    <div className={styles.niiViewerHeader}>
      <h3 className={styles.viewerTitle}>NIfTI Viewer</h3>
