/* Related Terms Tags */
.relatedTagsContainer {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  overflow-x: auto; /* Use horizontal scrolling */
  overflow-y: visible; /* Allow triangle indicator to show */
  flex-wrap: nowrap;   /* Use horizontal scrolling */
  padding: 6px 0;
  padding-top: 20px; /* Extra space for triangle to show above */
  scrollbar-width: thin;
  position: relative;
  z-index: 10; /* Lower than autocomplete popup (50) to avoid blocking clicks */
  flex: 1; /* Occupy bottom half space */
  margin-top: -10px; /* Pull up to compensate for extra padding */
  pointer-events: none; /* Don't capture mouse events on container itself */
}

.relatedTag {
  padding: 0.25rem 0.7rem;
  background-color: rgba(64, 224, 208, 0.15); /* Light Tiffany */
  color: var(--tiffany-dark);
  border: 1px solid var(--tiffany-primary);
  border-radius: 16px;
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;
  position: relative; /* For hover indicator */
  z-index: 10; /* Ensure tag and its triangle are above other elements */
  pointer-events: auto; /* Enable mouse events for the tag itself */
}

