/**
 * LogicOperatorButtons - 邏輯運算符和括號按鈕
 * A presentational component that calls a parent function on click.
 */
import React, { useContext } from 'react';
import { SearchContext } from '../../context/SearchContext.jsx';
import { OPERATORS } from '../../utils/constants';
import styles from './SearchBar.module.css';

export function LogicOperatorButtons({ onOperatorClick, onBracketClick, focusedIndex, onMouseEnter }) {
  const { operator } = useContext(SearchContext);

  // 邏輯運算符 + 括號 + 座標按鈕
  const allButtons = [
    ...OPERATORS,
    { id: 'LPAREN', label: '(', symbol: '(' },
    { id: 'RPAREN', label: ')', symbol: ')' },
    { id: 'COORD', label: '[,,]', symbol: '[,,]', isCoord: true },
  ];

  const handleClick = (op, index) => {
    if (op.isCoord) {
      onBracketClick?.(op.label, index);
    } else {
      onOperatorClick?.(op.label);
    }
  };

  return (
    <div className={styles.operatorGroup}>
      {allButtons.map((op, index) => (
        <button
          key={op.id}
          className={`${styles.operatorButton} ${operator === op.id ? styles.active : ''} ${focusedIndex === index ? styles.focused : ''}`}
          onClick={() => handleClick(op, index)}
          title={op.isCoord ? 'Click to insert coordinates (cursor will be at first comma)' : 'Click to insert at cursor'}
          onMouseEnter={onMouseEnter}
          type="button"
        >
          {op.label}
        </button>
      ))}
    </div>
  );
}

const handleOperatorClick = useCallback((operator) => {
  setQuery(prevQuery => {
    const trimmed = prevQuery.trim();
    if (trimmed === '') {
      // 空查詢時，不插入運算符
      return '';
    }
    // 如果已以空格結尾，直接追加；否則先加空格再追加運算符和空格
    const suffix = trimmed.endsWith(' ') ? operator : ` ${operator}`;
    return `${trimmed}${suffix} `;
  });
  // 注意：SearchInput 元件內部會自動聚焦，無需在此處理
}, [setQuery]);

// 處理括號和座標按鈕
const handleBracketClick = useCallback((symbol, focusedIndexForBracket) => {
  setQuery(prevQuery => {
    const trimmed = prevQuery.trim();
    if (symbol === '[,,]') {
      // 座標按鈕：插入 [-,-,-] 並設置游標到第一個逗號前
      const newQuery = trimmed === '' ? '[-,-,-]' : `${trimmed} [-,-,-]`;
      // 延遲設置游標位置到下個事件循環
      setTimeout(() => {
        const cursorPos = newQuery.lastIndexOf('[') + 1; // 移到第一個逗號前
        inputRef.current?.setSelectionRange(cursorPos, cursorPos);
        inputRef.current?.focus();
      }, 0);
      return newQuery;
    } else {
      // 括號按鈕 ( 或 )：直接追加
      const suffix = trimmed.endsWith(' ') || trimmed === '' ? symbol : ` ${symbol}`;
      return `${trimmed}${suffix}`;
    }
  });
}, [setQuery]);

