const handleKeyDown = (e) => {
  const { key } = e;

  // Handle left/right arrow for cursor movement and clear button navigation
  // These should NOT propagate to parent (SearchContainer)
  if (key === 'ArrowRight' && showClearButton && query) {
    const cursorPosition = e.target.selectionStart;
    const textLength = query.length;

    // If cursor is at the end, focus clear button
    if (cursorPosition === textLength) {
      e.preventDefault();
      clearButtonRef.current?.focus();
      return;
    }
    // Otherwise allow normal cursor movement (don't preventDefault)
    return;
  }

  if (key === 'ArrowLeft') {
    // Allow normal left arrow cursor movement in input
    // This is at the input level, not parent level
    return;
  }

  // All other keys can be handled by parent (UpArrow, DownArrow, Escape, etc)
  onKeyDown?.(e);

  // 如果沒有被消費，再檢查 Enter 是否觸發搜尋
  if (!e.defaultPrevented && e.key === 'Enter') {
    if (query && query.trim().length > 0) {
      onSearch?.(query.trim());
    }
  }
};

{showClearButton && query && (
  <button
    ref={clearButtonRef}
    onClick={handleClear}
    onKeyDown={(e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        handleClear();
      } else if (e.key === 'ArrowLeft') {
        e.preventDefault();
        inputRef.current?.focus();
        // Set cursor to end of text
        const length = query.length;
        inputRef.current?.setSelectionRange(length, length);
      } else if (e.key === 'ArrowUp') {
        // Allow ArrowUp to go to operators level
        e.preventDefault();
        onKeyDown?.(e);
      }
      // Note: Other keys are not handled, so they don't propagate
    }}
    className={styles.clearButton}
    aria-label="Clear search"
    title="Clear search (→ to navigate here, ← to go back)"
  >
    ✕
  </button>
)}

