.operatorButton {
  padding: 0.2rem 0.6rem;
  background: var(--coral-primary);
  border: 1px solid transparent;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s ease;
  color: white;
  position: relative; /* For hover indicator */
}

.operatorButton:hover,
.operatorButton.focused {
  background: var(--coral-dark);
  border-color: var(--coral-light);
  color: black;
}

.operatorButton.active {
  background: var(--coral-dark);
  border-color: var(--coral-light);
}

.operatorButton::before {
  content: '▼';
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  opacity: 0;
  transition: all 0.2s ease;
  color: var(--coral-dark);
  font-size: 0.8rem;
  pointer-events: none;
  z-index: 100; /* High z-index to overlay search input */
}

.operatorButton:hover::before,
.operatorButton.focused::before {
  opacity: 1;
  top: 115%;
}

