                      onKeyDown?.(e);
                    }}
                    disabled={loading}
                    title="Click to insert at cursor"
                    onMouseEnter={() => onMouseEnter?.(index)}
                    data-tooltip={`co-occurrence: ${item.co_count}, jaccard: ${item.jaccard?.toFixed(4) || 'N/A'}`}
                  >
                    {item.term}
                  </button>      ))}
"}

