edits.text:
.directionButton {
  padding: 6px 10px;
  font-size: 14px;
  font-weight: 600;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  background-color: var(--bg-main);
  color: var(--text-primary);
  cursor: pointer;
  transition: all 0.2s ease;
  min-width: 40px;
  text-align: center;
}

.directionButton:focus {
  outline: 2px solid var(--coral-primary);
  outline-offset: 2px;
}

.directionButton:hover {
  background-color: var(--bg-main);
  border-color: var(--coral-primary);
  color: var(--coral-primary);
  transform: scale(1.05);
}

.directionButton:active {
  background-color: var(--coral-primary);
  border-color: var(--coral-primary);
  color: white;
  transform: scale(0.95);
}

.paginationBtn {
  padding: 0.5rem 0.75rem;
  background-color: var(--bg-main);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s;
  font-weight: 500;
  color: var(--text-primary);
}

.paginationBtn:hover:not(:disabled) {
  background-color: var(--bg-main);
  border-color: var(--coral-primary);
  color: var(--coral-primary);
}

.paginationBtn:focus {
  outline: 2px solid var(--coral-primary);
  outline-offset: 2px;
}

.paginationBtn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.paginationBtn.active {
  background-color: var(--coral-primary);
  border-color: var(--coral-primary);
  color: white;
}

