/**
 * SearchContainer Component
 * Complete search integration with a two-column layout matching the prototype.
 * Handles search logic, autocomplete, operator buttons, and related terms.
 */
import React, { useContext, useEffect, useState, useRef, useCallback } from 'react';
import { useDebounce } from '../../hooks';
import { useToast } from '../../hooks/useToast';
import { SearchContext } from '../../context/SearchContext.jsx';
import { fetchTerms, fetchRelatedTerms } from '../../utils/api';
import { SearchInput, AutocompletePopup, LogicOperatorButtons, RelatedTermsTags } from './index';
import styles from './SearchBar.module.css';

export function SearchContainer({ onSearch }) {
  const { query, setQuery, relatedTerms, setRelatedTerms, setLoading } = useContext(SearchContext);
  const toast = useToast();

  const [suggestions, setSuggestions] = useState([]);
  const [selectedSuggestionIndex, setSelectedSuggestionIndex] = useState(-1);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [allTerms, setAllTerms] = useState([]);
  const [relatedLoading, setRelatedLoading] = useState(false);

// Auto-search when query changes (debounced)
useEffect(() => {
  const trimmedQuery = debouncedQuery.trim();

  // 🧪 Toast 測試功能
  if (trimmedQuery === 'test-success') {
    toast.success('Exported 5 studies as CSV');
    return;
  }
  if (trimmedQuery === 'test-warning') {
    toast.warning('No studies to export');
    return;
  }
  if (trimmedQuery === 'test-warning2') {
    toast.warning('Please enter a search term');
    return;
  }
  if (trimmedQuery === 'test-error') {
    toast.error('Failed to export: Network error');
    return;
  }
  if (trimmedQuery === 'test-info') {
    toast.info('This is an info message');
    return;
  }
  if (trimmedQuery === 'test-all') {
    setTimeout(() => toast.success('Success notification'), 100);
    setTimeout(() => toast.warning('Warning notification'), 600);
    setTimeout(() => toast.error('Error notification'), 1100);
    setTimeout(() => toast.info('Info notification'), 1600);
    return;
  }

  if (trimmedQuery.length > 0) {
    onSearchRef.current?.(trimmedQuery);
  }
}, [debouncedQuery, toast]);

