.citeButton {
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 400;
  border: 1px solid var(--coral-primary);
  border-radius: 6px;
  background-color: transparent;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 6px;
}

.citeButton:hover {
  background-color: transparent;
  border-color: var(--coral-primary);
  color: var(--coral-primary);
  box-shadow: 0 0 0 2px rgba(255, 127, 80, 0.2);
}

.citeButton:active {
  background-color: transparent;
