edits.text:
/**
 * ToastContainer 樣式
 * 固定位置在左下角，允許堆疊多個通知
 */

.toastContainer {
  position: fixed;
  bottom: 20px;
  left: 20px;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-width: 500px;
  pointer-events: auto;
}

/* 響應式設計 */

@media (max-width: 768px) {
  .toastContainer {
    bottom: 10px;
    left: 10px;
    right: 10px;
    max-width: none;
  }
}

@media (max-width: 480px) {
  .toastContainer {
    bottom: 5px;
    left: 5px;
    right: 5px;
    max-width: none;
  }
}

@keyframes slideIn {
  from {
    transform: translateX(-100%);
    opacity: 0;
  }
  to {
    transform: translateX(0);
    opacity: 1;
  }
}

@keyframes slideOut {
  from {
    transform: translateX(0);
    opacity: 1;
  }
  to {
    transform: translateX(-100%);
    opacity: 0;
  }
}

